(()=>{'use strict';
const STORE='curis-cg-codex-exploration-v1';
const copy=x=>JSON.parse(JSON.stringify(x));
let S;try{S=JSON.parse(localStorage.getItem(STORE))||copy(SEED)}catch{S=copy(SEED)}
for(const [k,v] of Object.entries(SEED)) if(!Array.isArray(S[k])) S[k]=copy(v);
let route={area:'operate',view:'portfolio'},scope='all',metric='views',compareMode='single',drawer=null,toastTimer;
const inlineOpen={},inlineDraft={},selections={};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=v=>esc(v), save=()=>localStorage.setItem(STORE,JSON.stringify(S));
const account=id=>S.accounts.find(a=>a.id===id), work=id=>S.works.find(w=>w.id===id), ref=id=>S.refs.find(r=>r.id===id);
const btn=(label,act,extra='',cls='')=>`<button type="button" class="${cls}" data-act="${act}" ${extra}>${label}</button>`;
const state=(s)=>`<span class="state ${/已|可|通过|接受|正式/.test(s)?'good':/等待|待|缺|未知/.test(s)?'wait':/失败|阻塞/.test(s)?'error':'info'}">${esc(s)}</span>`;
const person=(name,role)=>`<div class="person"><span class="avatar">${esc(name[0])}</span><div><strong>${esc(name)}</strong><small>${esc(role)}</small></div></div>`;
const navs=[['operate','经营','◫'],['research','研究与选题','⌕'],['production','内容制作','▣'],['publish','发布','↗'],['accounts','账号','◎'],['analytics','复盘','▥'],['assets','素材','◇']];
function go(area,view,id){location.hash=[area,view||'',id||''].filter(Boolean).map(encodeURIComponent).join('/');}
function parse(){let [area,view,id]=(location.hash.slice(1)||'operate/portfolio').split('/').map(decodeURIComponent);route={area:navs.some(n=>n[0]===area)?area:'operate',view:view||'index',id:id||''};if(route.area==='operate'&&route.view==='index')route.view='portfolio';render();}
function shell(){const current=navs.find(n=>n[0]===route.area);$('#nav').innerHTML=`<div class="brand">curis<small>Content Growth</small></div><div class="nav-title">专业工作区 · 演示业务</div><div class="nav-links">${navs.map(([id,label,icon])=>`<button type="button" class="nav-item ${route.area===id?'active':''}" data-go="${id}/${id==='operate'?'portfolio':id==='research'?'market':id==='production'?'queue':id==='publish'?'queue':id==='accounts'?'index':id==='analytics'?'overview':'library'}"><span class="ico">${icon}</span>${label}</button>`).join('')}</div><div class="nav-foot">独立 HTML 产品探索<br>所有市场与平台读数均为 Mock<br>${btn('重置演示数据','reset','','small')}</div>`;
$('#topbar').innerHTML=`<div>Curis / Content Growth / <b>${current[1]}</b>${route.id?` / <b>${esc(route.id)}</b>`:''}</div><div class="scope"><span class="tag">演示数据 · 无真实平台连接</span>${route.area==='operate'&&route.view==='account'?'':`<label style="margin:0" for="account-scope">账号范围</label><select id="account-scope" aria-label="账号范围"><option value="all">全部账号</option>${S.accounts.map(a=>`<option value="${a.id}" ${scope===a.id?'selected':''}>${esc(a.platform+'｜'+a.name)}</option>`).join('')}</select>`}</div>`;}
function head(k,title,desc='',actions=''){return `<div class="head"><div><div class="eyebrow">${k}</div><h1>${esc(title)}</h1>${desc?`<p>${desc}</p>`:''}</div><div class="actions">${actions}</div></div>`}
function employee(name,role,context){return `<div class="employee-strip">${person(name,role)}<span class="statusline">${esc(context)}</span>${btn('与'+name+'交流','chat',`data-person="${attr(name)}" data-context="${attr(context)}"`,'small')}</div>`}
function footer(){return `<div class="footer-note">产品探索 · 事实与状态仅保存在此浏览器。外部平台采集、发布、授权与执行均未连接；“已发布”只表示演示中经人工核验的状态。</div>`}
function operate(){if(route.view==='account')return operateAccount();let primary=S.accounts[0];return head('BUSINESS OPERATING','经营整个账号组合','林岚维护目标、内容供应与授权边界；研究、制作、发布、复盘可同时推进。',btn('进入研究现场','jump','data-to="research/market"','primary'))+
 employee('林岚','Content Growth 团队负责人','当前账号组合 · 目标、供应与下一轮')+
 `<div class="split-wide"><div><div class="focus"><div class="eyebrow">林岚的当前判断 · 09:40</div><div class="judgment">保持小红书品牌号的每周 3 篇节奏，先把两篇图文模板化；抖音创始人 IP 两天后可能断档，但出镜授权未确认，不能自动安排发布。</div><div class="actions">${btn('查看依据','jump','data-to="analytics/overview"')}${btn('调整策略与节奏','chat','data-person="林岚" data-context="调整账号组合的策略与节奏"')}${btn('准备下一轮','next-cycle','','primary')}</div></div><div class="operating-ledger"><div><small>本轮目标</small><strong>3 个账号</strong><small>各自节奏独立</small></div><div><small>正在推进</small><strong>${S.works.filter(w=>w.state==='制作中').length} 项制作</strong><small>多员工并行</small></div><div><small>待外部确认</small><strong>1 项授权</strong><small>不可自动越界</small></div><div><small>下一检查</small><strong>明日 10:00</strong><small>观察库存与反馈</small></div></div><div class="section"><h2>账号组合 · 点击进入经营</h2><div class="account-row header"><span>平台</span><span>账号 / 目标</span><span>本轮重点</span><span>供应</span><span></span></div>${S.accounts.map(a=>`<div class="account-row"><span class="platform"><span class="logo">${a.mark}</span>${a.platform}</span><div><strong>${esc(a.name)}</strong><br><small>${esc(a.goal)}</small></div><span class="optional">${esc(a.focus)}</span><span>${esc(a.supply)}</span><div>${btn('进入经营','jump',`data-to="operate/account/${a.id}"`,'small')}</div></div>`).join('')}</div></div><aside><div class="section"><h2>团队已处理 / 正在处理 / 等你决定</h2>${S.activity.map(x=>`<div class="listrow"><div>${state(x.kind)}<p style="margin-top:7px;color:var(--ink)">${esc(x.text)}</p><small>${esc(x.time)}</small></div></div>`).join('')}</div><div class="section"><h2>经营边界</h2><p class="meta">目标账号、发布频率、品牌资产、预算、授权和必须人工复核的场景，限定团队自主经营范围。</p><div class="finding">出镜授权不足时，可继续制作预览，不可把内容当作已获准发布。</div>${btn('和林岚讨论边界','chat','data-person="林岚" data-context="经营边界与授权"','small')}</div></aside></div>`+footer();}
function operateAccount(){let a=account(route.id)||S.accounts[0],ws=S.works.filter(w=>w.account===a.id);return head('ACCOUNT OPERATING',a.platform+'｜'+a.name,'这个账号的目标、策略与节奏在此经营；绑定和身份资料在「账号」维护。',btn('查看账号档案','jump',`data-to="accounts/detail/${a.id}"`))+
 employee('林岚','经营负责人',a.platform+'｜'+a.name+' · 当前经营判断')+
 `<div class="split"><div><div class="focus"><div class="eyebrow">目标 → 当前偏差 → 调度</div><h2>${esc(a.goal)}</h2><p class="judgment">${esc(a.note)}</p><div class="actions">${btn('调整策略','chat',`data-person="林岚" data-context="${attr(a.platform+'｜'+a.name+' 策略调整')}"`)}${btn('调整节奏','chat',`data-person="林岚" data-context="${attr(a.platform+'｜'+a.name+' 发布节奏')}"`)}${btn('看复盘依据','jump','data-to="analytics/overview"')}</div></div><div class="section"><h2>这个账号正在发生的工作</h2>${ws.map(w=>`<div class="listrow"><div><h3>${esc(w.title)}</h3><p>${esc(w.method)} · ${esc(w.step)} · ${esc(w.owner)} · ${esc(w.next)}</p></div>${btn('进入工作','jump',`data-to="production/work/${w.id}"`,'small')}</div>`).join('')||'<p class="meta">当前没有制作工作，Leader 可从研究中安排下一轮。</p>'}</div><div class="section"><h2>下一轮</h2><p>当前重点：${esc(a.focus)}。先检查库存与观察窗，再决定继续、实验或改变投入。</p>${btn('从市场找机会','jump','data-to="research/market"','primary')}</div></div><aside><div class="paper"><h2>经营节奏</h2><dl class="anatomy"><dt>阶段</dt><dd>${esc(a.stage)}</dd><dt>发布节奏</dt><dd>${esc(a.rhythm)}</dd><dt>内容供应</dt><dd>${esc(a.supply)}</dd><dt>准备状态</dt><dd>${state(a.status)}</dd></dl></div><div class="section"><h2>最近结果</h2><p class="meta">账号数据与内容数据使用不同口径。当前演示仅有部分内容观察，不以 Unknown 代替 0。</p>${btn('看具体内容表现','jump','data-to="analytics/overview"')}</div></aside></div>`+footer()}
function research(){const tabs=[['market','市场观察'],['watch','持续关注'],['reference','参考拆解'],['topics','选题与提案']];let sub=`<div class="subnav">${tabs.map(([id,t])=>`<button type="button" class="${route.view===id?'on':''}" data-go="research/${id}">${t}</button>`).join('')}</div>`;if(route.view==='watch')return watchPage(sub);if(route.view==='reference')return referencePage(sub);if(route.view==='topics'||route.view==='proposal')return topicsPage(sub);return marketPage(sub)}
function marketPage(sub){return head('MARKET INTELLIGENCE','市场正在发生什么','这是一组演示观察，不是平台官方热榜。观察范围与来源可进入「持续关注」调整。',btn('管理关注范围','jump','data-to="research/watch"'))+employee('沈述','研究与选题负责人','近 24 小时 · 机会发现与来源核对')+sub+`<div class="scope-bar"><div class="between"><strong>观察范围：职场 AI × 目标受众</strong><span class="tag">近 24 小时 · 3 个来源</span></div><p>关键词、对标账号与用户反馈；最近检查 09:20；浏览器可见页面 / 手动样本，均为 Mock。</p></div><div class="split-wide"><div><div class="section"><h2>变化值得看，不等于值得做</h2>${S.signals.map(s=>`<div class="signal"><span class="rise">${esc(s.change)}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.platform)} · ${esc(s.window)} · ${esc(s.source)} · ${esc(s.seen)}</p></div><span class="optional">${state('待解释')}</span>${btn('研究信号','jump',`data-to="research/reference/${s.id}"`,'small')}</div>`).join('')}</div><div class="section"><h2>过去几次观察</h2><div class="mini-timeline">${[24,34,29,48,58,64,83].map(n=>`<span style="height:${n}%"></span>`).join('')}</div><div class="spark-note"><span>7 次演示快照</span><span>变化仅为 Mock 相对热度</span></div></div></div><aside><div class="paper"><h2>沈述的判断</h2><p>岗位替代的讨论升温，但评论想要的是可操作的任务拆解；先拆参考，再判断是否适合品牌号或创始人 IP。</p>${btn('查看已有参考','jump','data-to="research/reference/ref0"','primary')}</div><div class="section"><h2>来源边界</h2><p class="meta">公开页面观察不意味着拥有平台 API。发现信号、评论与播放字段可能缺失；记录来源和采集时间，不冒充完整平台数据。</p></div></aside></div>`+footer()}
function watchPage(sub){return head('RESEARCH SCOPE','持续关注','员工在这里管理研究任务：关注什么、从哪里看、多久检查、什么时候暂停。',btn('新增关注','watch-form','','primary'))+employee('沈述','研究负责人','当前研究范围与检查节奏')+sub+`<div class="watch-grid">${S.watch.map(w=>`<article class="watch-item"><div class="actions" style="justify-content:space-between"><strong>${esc(w.name)}</strong>${state(w.state)}</div><p>${esc(w.platform)} · ${esc(w.kind)}</p><dl class="anatomy"><dt>检查频率</dt><dd>${esc(w.frequency)}</dd><dt>最近检查</dt><dd>${esc(w.last)}</dd><dt>观察方式</dt><dd>${esc(w.method)}</dd></dl><div class="actions">${btn('修改','watch-form',`data-id="${w.id}"`,'small')}${btn(w.state==='已暂停'?'恢复':'暂停','watch-toggle',`data-id="${w.id}"`,'small')}${btn('立即检查','watch-check',`data-id="${w.id}"`,'small')}${btn('移除','watch-remove',`data-id="${w.id}"`,'small danger')}</div></article>`).join('')}</div><div class="section"><p class="meta">检查属于产品演示：会记录一次新快照时间；不会调用真实浏览器、API 或 MCP。缺少来源授权时保持 Unknown。</p></div>`+footer()}
function referencePage(sub){let r=ref(route.id)||S.refs[0],signal=S.signals.find(s=>s.id===route.id);if(signal&&!ref(route.id)){return head('SIGNAL → REFERENCE','研究这个变化',signal.context,btn('返回市场','jump','data-to="research/market"'))+employee('沈述','研究负责人',signal.title)+sub+`<div class="split"><div class="paper"><h2>${esc(signal.title)}</h2><p>${esc(signal.platform)} · ${esc(signal.window)} · ${esc(signal.source)}</p><div class="pattern-band"><strong>需要先回答</strong><p>这个变化来自什么样的内容？可见证据是什么？哪些信息仍未知？不复制原内容。</p></div><div class="actions">${btn('建立参考并拆解','signal-to-ref',`data-id="${signal.id}"`,'primary')}${btn('与沈述讨论','chat',`data-person="沈述" data-context="${attr(signal.title)}"`)}</div></div><aside class="paper"><h2>发现时间</h2><p>${esc(signal.seen)}</p><h2>变化</h2><p>${esc(signal.change)}</p><h2>限制</h2><p>热度并非账号表现；来源字段为 Mock。</p></aside></div>`+footer()}
return head('REFERENCE ANALYSIS','把参考拆成可复用的方法',r.title,btn('返回市场','jump','data-to="research/market"'))+employee('沈述','参考拆解负责人',r.title+' · 来源、证据与适用范围')+sub+`<div class="reference-canvas"><div><div class="reference-stage"><div class="reference-poster"><span>来源预览 · 演示构图</span><strong>${esc(r.hook)}</strong><span>${esc(r.source)}</span></div><div class="caption">示意画面，不复制外部视频或封面</div></div><div class="section"><div class="eyebrow">WHY IT MAY WORK</div><h2>为什么值得学</h2><p>${esc(r.why)}</p><div class="pattern-band"><strong>可复用 Pattern</strong><p>${esc(r.pattern)}</p></div><div class="actions">${btn('从这个方法形成选题','ref-to-topic',`data-id="${r.id}"`,'primary')}${btn('与沈述讨论','chat',`data-person="沈述" data-context="${attr('参考 '+r.title+' 的拆解与备注')}"`)}</div></div></div><aside><div class="paper"><h2>内容结构</h2><dl class="anatomy">${[['Hook',r.hook],['Opening',r.opening],['Structure',r.structure],['Rhythm',r.rhythm],['Visual',r.visual],['CTA',r.cta],['评论反馈',r.feedback]].map(([a,b])=>`<dt>${a}</dt><dd>${esc(b)}</dd>`).join('')}</dl></div><div class="section"><h2>来源与边界</h2><p class="meta">${esc(r.source)} · 发布 ${esc(r.published)} · 采集 ${esc(r.captured)}</p><p class="meta">证据：${esc(r.evidence)}</p><p class="meta">适用：${esc(r.fit)}<br>限制：${esc(r.limit)}</p></div></aside></div>`+footer()}
function topicsPage(sub){if(route.view==='proposal'&&route.id)return proposalDetail(sub);return head('RESEARCH → PRODUCTION','把发现变成可执行内容','选题可以保持开放；提案必须明确目标账号、经营任务、内容形态和成功判据。',btn('从市场找机会','jump','data-to="research/market"'))+employee('沈述','研究与选题负责人','选题成熟后交制作团队')+sub+`<div class="split"><div><div class="section"><h2>选题池</h2>${S.topics.map(t=>`<div class="listrow"><div><h3>${esc(t.title)}</h3><p>${esc(t.note)} · ${esc(account(t.account)?.platform||'未定账号')}</p></div><div class="row-actions">${state(t.stage)}${btn('形成提案','topic-to-proposal',`data-id="${t.id}"`,'small')}</div></div>`).join('')}</div><div class="section"><h2>制作提案</h2>${S.proposals.map(p=>`<div class="listrow"><div><h3>${esc(p.title)}</h3><p>${esc(account(p.account)?.platform||'未定')}｜${esc(account(p.account)?.name||'未定')} · ${esc(p.method)} · ${esc(p.goal)}</p></div>${btn('打开提案','jump',`data-to="research/proposal/${p.id}"`,'small')}</div>`).join('')}</div></div><aside class="paper"><h2>接力原则</h2><p>Reference 保留来源与可借鉴结构；选题提出方向；提案才确认目标账号、成功判据与制作要求。</p><p class="meta">同一个选题可以为不同账号提出不同交付；不会因为“开工”而偷偷复用平台目标。</p></aside></div>`+footer()}
function proposalDetail(sub){let p=S.proposals.find(x=>x.id===route.id)||S.proposals[0],a=account(p.account),r=ref(p.source);return head('CONTENT PROPOSAL',p.title,'目标账号、经营目的和生产约束已明确，确认后才交制作。',btn('返回选题','jump','data-to="research/topics"'))+employee('沈述','提案负责人',p.title+' · 与制作交接')+sub+`<div class="split"><div class="focus"><div class="eyebrow">为什么现在做</div><p class="judgment">${esc(p.why)}</p><dl class="anatomy"><dt>目标账号</dt><dd>${esc(a?.platform+'｜'+a?.name)}</dd><dt>经营任务</dt><dd>${esc(p.goal)}</dd><dt>内容形态</dt><dd>${esc(p.method)}</dd><dt>成功判据</dt><dd>${esc(p.criterion)}</dd><dt>限制</dt><dd>${esc(p.limits)}</dd><dt>当前状态</dt><dd>${state(p.state)}</dd></dl><div class="actions">${btn('确认并交制作','proposal-start',`data-id="${p.id}"`,'primary')}${btn('与沈述调整提案','chat',`data-person="沈述" data-context="${attr('提案 '+p.title)}"`)}</div></div><aside><div class="paper"><h2>来源与方法</h2><p>${esc(r?.title||'用户意图 / 历史经验')}</p><div class="pattern-band">${esc(r?.pattern||'保留已引用的方法来源')}</div>${r?btn('回到参考','jump',`data-to="research/reference/${r.id}"`):''}</div><div class="section"><h2>交付后</h2><p class="meta">Work 继承提案身份与目标账号；Employee 可调整方法，但权限与发布边界仍按账号核验。</p></div></aside></div>`+footer()}
function production(){if(route.view==='work')return workPage();let groups=['图文','口播','视频','长文章'];return head('PRODUCTION','内容制作','按制作方式看工作，进入具体 Work 才查看专业产物与当前负责人。',btn('从提案开工','jump','data-to="research/topics"'))+employee('周砚','制作统筹','各方法产线 · 多项 Work 并行')+groups.map(g=>{let ws=S.works.filter(w=>w.method===g&&(!scope||scope==='all'||w.account===scope));return `<div class="method-group"><h2>${g}<small>${ws.length} 项相关 Work</small></h2>${ws.length?ws.map(w=>`<div class="workrow"><div><strong>${esc(w.title)}</strong><br><small>${esc(w.id)} · ${esc(w.artifact)}</small></div><span>${esc(account(w.account)?.platform+'｜'+account(w.account)?.name)}</span><span>${esc(w.step)}</span><span>${esc(w.owner)}</span><span class="optional">${state(w.state)}</span><div>${btn('进入','jump',`data-to="production/work/${w.id}"`,'small')}</div></div>`).join(''):`<div class="empty">当前范围没有${g}工作；从提案确认后进入队列。</div>`}</div>`}).join('')+footer()}
function steps(w){return w.method==='图文'?['制作提纲','页序与文案','视觉排版','把关']:w.method==='口播'?['Brief','脚本','数字人口播','后期','把关']:w.method==='长文章'?['大纲','正文','事实核验','把关']:['脚本','镜头','剪辑','字幕','把关']}
function artifact(w){if(w.method==='图文')return `<div class="page-strip">${(w.pages||['封面','问题','拆解','方法','行动']).map((x,i)=>`<div class="page-tile" id="region-${i+1}"><small>0${i+1} / 05</small><b>${esc(x)}</b><small>${i===0?'一句话说清核心问题':'让读者能照做'}</small>${btn('讨论这页','select-inline',`data-id="${w.id}" data-locator="页 ${i+1}" data-excerpt="${attr(x)}" data-anchor="region-${i+1}"`,'small')}</div>`).join('')}</div><p class="meta" style="margin-top:15px">页序与版式为 HTML 示意，非真实设计文件。</p>`;if(w.method==='口播'){let parts=w.scriptParts||['你担心 AI 会抢走你的工作吗？先看你每天做的五件事。','把重复搜集、整理、初稿交给工具；把判断和关系留给自己。','今天选一项工作，试着拆成目标、输入、检查三个步骤。'];return `<div class="script">${parts.map((t,i)=>`<p id="script-${i+1}"><small>${['00:00–00:03 · 开头','00:04–00:23 · 场景','00:24–00:60 · 行动'][i]||'脚本段落'}</small><br>${esc(t)}<br>${btn('讨论这段','select-inline',`data-id="${w.id}" data-locator="脚本第 ${i+1} 段" data-excerpt="${attr(t)}" data-anchor="script-${i+1}"`,'small')}</p>`).join('')}</div><div class="pattern-band">数字人：言舟 v2 · 声音与形象授权待确认 · 当前仅为 Mock 预览${w.videoNeedsReview?' · 脚本已更新，成片尚未重新核验':''}</div>`}if(w.method==='长文章')return `<div class="script"><h2>从工具焦虑到工作方法</h2><p>真正值得改变的不是一天安装多少工具，而是把工作拆成能验证的步骤。先知道结果，再决定哪些部分交给 AI。</p><p>在开始之前，把目标、已有材料和必须由人判断的边界写在同一张纸上。</p></div>`;return `<div class="storyboard">${(w.shots||['开场疑问','真实工作场景','任务拆解','关键对照','可做的第一步','收束']).map((x,i)=>`<div class="shot" id="shot-${i+1}"><small>镜头 ${i+1}</small><strong>${esc(x)}</strong><small>画面 / 字幕占位</small>${btn('讨论镜头','select-inline',`data-id="${w.id}" data-locator="镜头 ${i+1}" data-excerpt="${attr(x)}" data-anchor="shot-${i+1}"`,'small')}</div>`).join('')}</div>`}
function inlineConversation(w){if(!inlineOpen[w.id])return '';const selected=selections[w.id],stale=selected&&selected.version!==w.version,context=w.id;let ms=S.messages.filter(m=>m.context===context&&m.name===w.owner);return `<section class="inline-conversation" aria-label="与${esc(w.owner)}讨论当前工作"><div class="inline-top"><strong>与${esc(w.owner)}讨论 · ${esc(w.title)}</strong>${btn('收起讨论','inline-toggle',`data-id="${w.id}"`,'small')}</div>${selected?`<div class="selection-context"><strong>当前选段</strong><span>${esc(selected.objectId)} · v${selected.version} · ${esc(selected.locator)} · ${esc(selected.excerpt.slice(0,78))}</span>${stale?state('基线已变化 · 请重新选择'):''}<div class="actions">${btn('定位原处','selection-locate',`data-id="${w.id}"`,'small')}${btn('移除引用','selection-remove',`data-id="${w.id}"`,'small')}</div></div>`:''}<div class="inline-messages"><div class="bubble"><small>${esc(w.owner)}</small>可以就当前工作或选段讨论。演示回复不调用模型；修改候选会回到下方专业产物中比较。</div>${ms.map(m=>`<div class="bubble ${m.role==='user'?'user':''}"><small>${m.role==='user'?'你':esc(w.owner)}${m.selection?' · 引用 '+esc(m.selection.locator)+' v'+m.selection.version:''}</small>${esc(m.text)}</div>`).join('')}</div><form id="inline-chat-form" data-id="${w.id}" class="inline-compose"><label for="inline-text">当前对象 ${esc(w.id)} · 目标员工 ${esc(w.owner)}${selected?' · '+esc(selected.locator):''}</label><textarea id="inline-text" name="text" required placeholder="告诉负责人你想调整什么，或询问这一段为什么这样处理…">${esc(inlineDraft[w.id]||'')}</textarea><div class="actions"><small>文本演示 · 不调用真实模型或平台</small><button class="primary" type="submit">发送</button>${btn('形成修订候选','revise',`data-id="${w.id}" ${stale?'disabled title="原版本已变化，请重新选择"':''}`,'small')}</div></form></section>`}
function workPage(){let w=work(route.id)||S.works[0],a=account(w.account),st=steps(w),idx=Math.max(0,st.indexOf(w.step)),sel=selections[w.id];return head('PRODUCTION WORK',w.title,`${a.platform}｜${a.name} · ${w.method} · ${w.id} · ${w.method==='口播'?'脚本':'产物'}版本 v${w.version}`,btn('返回制作队列','jump','data-to="production/queue"'))+
 `<div class="worktop">${state(w.state)}<span class="meta">来源：${esc(w.source)} · Work 负责人：${esc(w.owner)}</span></div><div class="employee-strip work-employee-bar">${person(w.owner,w.step+' · 当前责任')}<span class="statusline">${esc(w.next)}</span>${btn(inlineOpen[w.id]?'收起讨论':'一起讨论','inline-toggle',`data-id="${w.id}"`,'small')}</div>${inlineConversation(w)}<div class="work-progress">${st.map((x,i)=>`<button type="button" class="${i<idx?'done':i===idx?'current':''}" data-act="step-note" data-step="${attr(x)}" data-id="${w.id}">${esc(x)} ${i<idx?'✓':i===idx?'●':''}</button>`).join('')}</div><div class="split-wide"><div><div class="artifact-stage"><div class="art-head"><div><div class="eyebrow">当前专业产物</div><h2>${esc(w.artifact)}</h2><span class="meta">版本 v${w.version} · 旧版本保留 · 不等于视频核验或发布</span></div>${btn('生成修订候选','revise',`data-id="${w.id}" ${sel&&sel.version!==w.version?'disabled title="原版本已变化，请重新选择"':''}`,'small')}</div>${artifact(w)}</div>${w.candidate?`<div class="section candidate-result" id="candidate-result"><div class="eyebrow">员工返回的修订候选 · 在专业 Main 审阅</div><h2>${esc(w.candidate.locator)} · 基于 v${w.candidate.baseVersion} → 候选 v${w.candidate.targetVersion}</h2><div class="candidate-compare"><div><small>当前正式工作版本</small><p>${esc(w.candidate.before)}</p></div><div><small>修订建议 · Mock</small><p>${esc(w.candidate.after)}</p></div></div><p class="meta">只改变所选脚本段落 / 镜头 / 专业 Artifact。查看不等于采纳；口播脚本采纳不代表数字人成片重新核验、发布或外部效果。</p><div class="actions">${btn('采纳此候选','candidate-accept',`data-id="${w.id}"`,'primary')}${btn('暂不采纳','candidate-reject',`data-id="${w.id}"`)}${btn('继续与'+w.owner+'讨论','inline-open',`data-id="${w.id}"`,'small')}</div></div>`:''}<div class="section"><h2>把关意见</h2>${w.review?`<div class="finding good"><strong>员工审查已完成</strong><p>证据：当前成品 v${w.version} 与目标账号约束已核对。风险：需确认授权和实际平台发布方式。</p><small>建议：确认当前版本；审查完成并不自动成为正式成品。</small></div>`:`<div class="finding"><strong>等待专业把关</strong><p>员工会结合内容形式、目标账号、事实与授权给出 Finding、Evidence、Impact 与 Recommendation。</p></div>`}<div class="actions">${btn('请员工检查当前版本','review',`data-id="${w.id}"`)}${w.review&&!w.accepted?btn('接受为待发布成品','accept',`data-id="${w.id}"`,'primary'):''}${w.accepted?state('已接受 · 待发布'):''}</div></div></div><aside class="production-side"><div class="paper"><h2>产物与责任</h2><dl class="anatomy"><dt>当前步骤</dt><dd>${esc(w.step)}</dd><dt>输入</dt><dd>${esc(w.source)}</dd><dt>成品</dt><dd>${esc(w.artifact)} · 工作版本 v${w.version}</dd><dt>下一步</dt><dd>${esc(w.next)}</dd></dl></div><details><summary>版本、输入与影响范围</summary><p>原版本 v1–v${w.version} 保留。修订候选在 Main 比较；采纳后重新把关，已发版本不会被静默替换。</p>${w.videoNeedsReview?'<p>脚本已变化；数字人成片仍是原版本，需另行核验。</p>':''}</details><div class="section">${btn('前往发布','jump','data-to="publish/queue"','small')}</div></aside></div>`+footer()}
function publish(){if(route.view==='item')return publicationDetail();return head('PUBLISHING','每条内容，分别确认外部结果','已接受成品进入发布；提交、平台回执与真实效果是不同事实。',btn('返回制作','jump','data-to="production/queue"'))+employee('唐枢','发布负责人','目标账号、权限、执行方式与回执核验')+`<div class="publication-lane"><div class="on">01 成品已接受</div><div class="on">02 指定账号与版本</div><div>03 提交 / 人工接续</div><div>04 回执与观察</div></div><div class="split"><div class="section"><h2>发布队列</h2>${S.publications.map(p=>{let w=work(p.work),a=account(p.account);return `<div class="listrow"><div><h3>${esc(w?.title||p.work)}</h3><p>${esc(a?.platform+'｜'+a?.name)} · 成品 v${p.version} · ${esc(p.mode)} · ${esc(p.receipt)}</p></div><div class="row-actions">${state(p.state)}${btn('继续','jump',`data-to="publish/item/${p.id}"`,'small')}</div></div>`}).join('')}<div class="section"><h2>可接入队列的成品</h2>${S.works.filter(w=>w.accepted&&!S.publications.some(p=>p.work===w.id)).map(w=>`<div class="listrow"><div><h3>${esc(w.title)}</h3><p>已接受 v${w.version} · ${esc(account(w.account)?.platform+'｜'+account(w.account)?.name)}</p></div>${btn('建立发布项','create-pub',`data-id="${w.id}"`,'small')}</div>`).join('')||'<p class="meta">当前没有新的已接受成品。制作审查通过后需要明确接受，再进入发布。</p>'}</div></div><aside class="paper"><h2>不能假定一次发布成功</h2><p>自动 API、计算机操作、人工发布都要核对账号、权限、版本与回执。</p><div class="finding">若外部效果未知，先核验；不可盲目重发。</div><p class="meta">登录失效、验证码、MFA、风控或权限变化时等待用户，不伪造自动发布。</p></aside></div>`+footer()}
function publicationDetail(){let p=S.publications.find(x=>x.id===route.id)||S.publications[0],w=work(p.work),a=account(p.account);return head('PUBLICATION',w?.title||p.work,`${a?.platform}｜${a?.name} · 已指定成品 v${p.version} · ${p.id}`,btn('返回发布队列','jump','data-to="publish/queue"'))+employee('唐枢','发布负责人',p.id+' · 执行方式与回执')+`<div class="publication-lane"><div class="on">已接受成品</div><div class="on">${esc(p.mode)}</div><div class="${p.state==='已核验上线'?'on':''}">${esc(p.state)}</div><div class="${p.state==='已核验上线'?'on':''}">观察窗口</div></div><div class="split"><div><div class="focus"><div class="eyebrow">实际状态</div><h2>${esc(p.state)}</h2><p>${esc(p.receipt)}</p><p class="meta">目标账号：${esc(a?.platform+'｜'+a?.name)} · 版本 v${p.version} · 观察窗口：${esc(p.window)}</p><div class="actions">${p.state==='等待人工发布'?btn('准备发布包','pub-package',`data-id="${p.id}"`,'primary'):''}${p.state==='等待人工发布'?btn('报告已在平台发布','pub-unknown',`data-id="${p.id}"`):''}${p.state==='外部效果未知'?btn('核验外部结果','verify-form',`data-id="${p.id}"`,'primary'):''}${p.state==='已核验上线'?btn('查看内容表现','jump','data-to="analytics/overview"','primary'):''}</div></div><div class="section"><h2>发布接续</h2><p>演示仅提供内容、目标与检查清单；不会真的下载文件、操作平台或提交内容。</p><dl class="anatomy"><dt>平台入口</dt><dd>${esc(a?.platform)} 官方创作者后台 · 外部操作</dd><dt>成品</dt><dd>${esc(w?.artifact)} v${p.version}</dd><dt>人工确认</dt><dd>平台链接、真实发布时间、截图 / 回执来源</dd><dt>未知结果</dt><dd>留在原发布项，先查证，不重发</dd></dl></div></div><aside><div class="paper"><h2>证据与回执</h2>${state(p.state)}<p style="margin-top:12px">${esc(p.receipt)}</p>${p.url?`<p class="meta">演示记录链接：${esc(p.url)}</p>`:''}<p class="meta">回执与数据可追溯到本发布项及成品版本；“已接受”不等于“已上线”。</p></div><div class="section">${btn('返回原制作 Work','jump',`data-to="production/work/${p.work}"`,'small')}</div></aside></div>`+footer()}
function accounts(){let a=account(route.id);if(route.view==='detail'&&a)return accountDetail(a);return head('ACCOUNT PORTFOLIO','账号的长期身份','这里管理账号来源、授权、定位与经营准备；目标与下一轮调度在「经营」。',btn('添加账号','account-form','','primary'))+employee('林岚','账号经营责任人','合法身份、连接与长期策略')+`<div class="split"><div><div class="account-row header"><span>平台</span><span>账号 / 定位</span><span>目标</span><span>准备</span><span></span></div>${S.accounts.map(x=>`<div class="account-row"><span class="platform"><span class="logo">${x.mark}</span>${esc(x.platform)}</span><div><strong>${esc(x.name)}</strong><br><small>${esc(x.focus)}</small></div><span class="optional">${esc(x.goal)}</span>${state(x.status)}<div>${btn('查看','jump',`data-to="accounts/detail/${x.id}"`,'small')}</div></div>`).join('')}</div><aside class="paper"><h2>添加不是自动绑定</h2><p>记录平台账号身份后，还需核实控制权、连接方式、权限与可用动作。</p><p class="meta">原型中的“添加”仅创建本地演示档案，不会访问平台账号或获取数据。</p></aside></div>`+footer()}
function accountDetail(a){let pubs=S.publications.filter(p=>p.account===a.id);return head('ACCOUNT IDENTITY',a.platform+'｜'+a.name,'身份、连接与历史在这里；经营判断不会在账号档案里重复维护。',btn('进入账号经营','jump',`data-to="operate/account/${a.id}"`)) +employee('林岚','账号经营责任人',a.platform+'｜'+a.name+' · 身份与准备')+`<div class="split"><div><div class="paper"><h2>账号身份与准备</h2><dl class="anatomy"><dt>平台</dt><dd>${esc(a.platform)}</dd><dt>名称</dt><dd>${esc(a.name)}</dd><dt>定位</dt><dd>${esc(a.focus)}</dd><dt>准备状态</dt><dd>${state(a.status)}</dd><dt>目标</dt><dd>${esc(a.goal)}</dd></dl><div class="actions">${btn('修改账号信息','account-form',`data-id="${a.id}"`)}${btn('移除本地档案','account-remove',`data-id="${a.id}"`,'danger')}</div></div><div class="section"><h2>关联发布</h2>${pubs.map(p=>`<div class="listrow"><div><h3>${esc(work(p.work)?.title||p.work)}</h3><p>${esc(p.mode)} · ${esc(p.receipt)}</p></div>${btn('查看','jump',`data-to="publish/item/${p.id}"`,'small')}</div>`).join('')||'<p class="meta">暂无发布记录。</p>'}</div></div><aside class="paper"><h2>连接边界</h2><p>未接入真实账号。连接、权限、发布方式和数据可得性必须分别核验。</p><div class="finding">移除本地档案不会删除已产生的历史 Work；若有引用，演示将要求先保留身份。</div></aside></div>`+footer()}
const metricNames={views:'播放量',saves:'收藏数',follows:'新增粉丝',completion:'完播率'};
function chart(series){const palette=['#557c3d','#45717e','#aa7644'],all=series.flatMap(x=>x.values.filter(Number.isFinite)),max=Math.max(...all,1),marks=series.map((x,j)=>{let points=x.values.map((v,i)=>Number.isFinite(v)?`${36+i*105},${205-v/max*165}`:null).filter(Boolean).join(' ');return `<polyline fill="none" stroke="${palette[j]}" stroke-width="3" points="${points}"/>${x.values.map((v,i)=>Number.isFinite(v)?`<circle cx="${36+i*105}" cy="${205-v/max*165}" r="4" fill="${palette[j]}"><title>${esc(x.name)} · 第 ${i+1} 次：${v}${metric==='completion'?'%':''}</title></circle>`:'').join('')}`}).join('');return `<svg viewBox="0 0 720 245" role="img" aria-label="${esc(metricNames[metric])}观察趋势"><line x1="30" y1="205" x2="692" y2="205" stroke="#ccd2c9"/><line x1="30" y1="120" x2="692" y2="120" stroke="#e4e7df"/><line x1="30" y1="40" x2="692" y2="40" stroke="#e4e7df"/>${marks}${Array.from({length:7},(_,i)=>`<text x="${25+i*105}" y="229" font-size="11" fill="#6f786f">D${i+1}</text>`).join('')}</svg>`}
function analytics(){if(route.view==='attribution')return attribution();if(route.view==='experiment')return experiment();if(route.view==='learning')return learning();let obs=S.observations[0],w=work(obs.work),a=account(obs.account),comp=compareMode==='account'?S.observations.filter(o=>o.account===obs.account):compareMode==='platform'?S.observations.filter(o=>['w2','w6'].includes(o.work)):[obs],series=comp.map(o=>({name:account(o.account)?.platform+'｜'+work(o.work)?.title,values:o[metric]}));return head('PERFORMANCE','先看表现，再判断原因','时间窗口、来源、账号和成品版本与趋势同屏；未知数据保持未知。',btn('查看内容归因','jump','data-to="analytics/attribution"','primary'))+employee('苏澈','分析负责人','表现、证据、假设与下一步')+`<div class="subnav"><button class="on" data-go="analytics/overview">表现概览</button><button data-go="analytics/attribution">内容归因</button><button data-go="analytics/experiment">实验</button><button data-go="analytics/learning">经营经验</button></div><div class="split-wide"><div><div class="chartbox"><div class="actions" style="justify-content:space-between"><div><div class="eyebrow">内容趋势 · 同一口径</div><h2>${esc(w?.title)}</h2></div><span class="tag">${esc(a?.platform+'｜'+a?.name)} · ${esc(obs.window)}</span></div><div class="metricbar">${[['single','单条内容'],['account','同账号内容'],['platform','同主题跨平台']].map(([k,l])=>btn(l,'compare',`data-id="${k}" aria-pressed="${compareMode===k}"`,'small')).join('')}</div><div class="metricbar">${Object.keys(metricNames).map(k=>btn(metricNames[k],'metric',`data-id="${k}" aria-pressed="${metric===k}"`,'small')).join('')}</div>${chart(series)}<div class="spark-note"><span>来源：${esc(obs.source)} · 发布后同龄窗 D1–D7</span><span>${esc(metricNames[metric])}${metric==='completion'?'（%）':''}</span></div><div class="metricbar">${series.map((x,i)=>`<span class="tag"><span style="color:${['#557c3d','#45717e','#aa7644'][i]}">●</span> ${esc(x.name)} · ${x.values.at(-1)===null?'不适用':x.values.at(-1)}</span>`).join('')}</div>${compareMode==='platform'?'<p class="meta">跨平台、跨形态仅并排观察同名指标；平台定义、分发与受众不同，不直接判断哪条“更好”。图文完播率不适用，保持 Unknown。</p>':'<p class="meta">累计指标按发布后同龄窗比较；样本、投放与发布时间差异仍可能改变解释。</p>'}</div><div class="section"><h2>按内容看，而不是模糊“本期”</h2><div class="account-row header"><span>平台</span><span>内容 / 账号</span><span>观察窗口</span><span>数据</span><span></span></div>${S.observations.map(o=>`<div class="account-row"><span>${esc(account(o.account)?.platform)}</span><div><strong>${esc(work(o.work)?.title)}</strong><br><small>${esc(account(o.account)?.name)} · 成品 v${o.version}</small></div><span class="optional">${esc(o.window)}</span><span>${o[metric]?.at(-1)===null?'不适用':esc(o[metric]?.at(-1)??'未知')+(metric==='completion'?'%':'')}</span><div>${btn('分析','jump','data-to="analytics/attribution"','small')}</div></div>`).join('')}</div></div><aside><div class="paper"><h2>苏澈的观察</h2><p>${esc(obs.change)}</p><p class="meta">${esc(obs.comments)}</p><div class="actions">${btn('分析为什么','jump','data-to="analytics/attribution"','primary')}${btn('补录数据','data-form',`data-id="${obs.id}"`,'small')}</div></div><div class="section"><h2>比较边界</h2><p class="meta">同账号的两条口播采用发布后同龄窗；同主题跨平台仅并排看可比字段。完播率只适用于视频，图文不记 0。</p><p class="meta">其余在制内容未发布，连续观察为 Unknown；不混入对比。</p></div></aside></div>`+footer()}
function attribution(){let o=S.observations.find(x=>x.id===route.id)||S.observations[0],w=work(o.work),r=ref('ref0');if(o.id!=='obs0')return head('CONTENT ATTRIBUTION',w.title,'该内容已有观察，但尚无经员工整理的内容归因。',btn('回到趋势','jump','data-to="analytics/overview"'))+employee('苏澈','分析负责人',w.title+' · 归因待研究')+`<div class="split"><div class="paper"><h2>已知观察</h2><p>${esc(o.change)}</p><p class="meta">${esc(o.source)} · ${esc(o.window)}</p><div class="finding">尚未核对该内容的 Hook、结构、评论样本与替代解释，不能套用另一条内容的分析结论。</div>${btn('和苏澈讨论分析','chat',`data-person="苏澈" data-context="${attr('内容 '+w.title+' 的归因')}"`,'primary')}</div><aside class="paper"><h2>下一步</h2><p>调取本内容的正式版本与相同窗口证据，形成 Observation、Evidence、Hypothesis、Recommendation 后再沉淀 Learning。</p></aside></div>`+footer();return head('CONTENT ATTRIBUTION','内容为什么可能发生变化',w.title+' · 成品 v'+o.version+' · 来源 '+o.source,btn('回到趋势','jump','data-to="analytics/overview"'))+employee('苏澈','分析负责人','Observation → Evidence → Hypothesis → Learning')+`<div class="split"><div><div class="focus"><div class="eyebrow">OBSERVATION · 观察</div><h2>前三秒留存上升，收藏仍需继续观察</h2><p>${esc(o.change)}</p></div><div class="section"><h2>证据 → 解释 → 下一步</h2><dl class="anatomy"><dt>内容与版本</dt><dd>${esc(w.title)} · 口播 v${o.version} · 使用参考「${esc(r?.title)}」</dd><dt>Evidence</dt><dd>${esc(o.comments)}。${esc(o.source)}。</dd><dt>内容拆解</dt><dd>Hook：先问“AI 会不会取代”；Opening：具体工作场景；Structure：误区 → 步骤 → 行动；CTA：任务清单。</dd><dt>Hypothesis</dt><dd>问题式开头可能更快让受众代入；评论中对可执行方法的需求较强。</dd><dt>替代解释</dt><dd>平台推荐、发布时间、账号阶段、话题热度、样本差异可能同时影响结果。</dd><dt>Recommendation</dt><dd>下一条测试“任务清单”开头，保持受众与观察窗尽量接近。</dd></dl><div class="actions">${btn('查看实验','jump','data-to="analytics/experiment"','primary')}${btn('生成经验候选','learning-candidate')}${btn('回原制作','jump',`data-to="production/work/${w.id}"`)}</div></div></div><aside><div class="paper"><h2>证据链</h2><p>发布内容 / 版本 → 内容结构 → 手动观察 → 评论样本 → 假设。</p><p class="meta">关联性不是确定因果；接受经验前需声明账号、平台、内容形式和可比条件。</p></div></aside></div>`+footer()}
function experiment(){let e=S.experiments[0];return head('SHORT-CYCLE EXPERIMENT','让猜测变成能再检验的工作',e.name,btn('查看归因依据','jump','data-to="analytics/attribution"'))+employee('苏澈','实验分析负责人','同一账号 · Hook 测试 · 观察中')+`<div class="split"><div><div class="focus"><div class="eyebrow">HYPOTHESIS</div><h2>${esc(e.hypothesis)}</h2><p>目标账号：${esc(account(e.account)?.platform+'｜'+account(e.account)?.name)}</p></div><div class="publication-lane"><div class="on">提出假设</div><div class="on">建立变体</div><div class="on">关联发布</div><div>等待可比观察</div></div><div class="section"><h2>同一个实验的连接</h2><dl class="anatomy"><dt>Variant</dt><dd>${esc(e.variants)}</dd><dt>Publication</dt><dd>${esc(e.publication)}</dd><dt>Observation</dt><dd>${esc(e.observation)}</dd><dt>当前 Result</dt><dd>${esc(e.result)}</dd><dt>下一判断</dt><dd>到观察窗以后再比较前三秒留存、完播与收藏；不要先宣称实验胜出。</dd></dl><div class="actions">${btn('查看观察数据','jump','data-to="analytics/overview"','primary')}${btn('讨论实验下一步','chat','data-person="苏澈" data-context="Hook A/B 实验与下一步"')}</div></div></div><aside class="paper"><h2>实验状态</h2>${state(e.state)}<p class="meta" style="margin-top:13px">没有新的真实发布和等条件样本，本次无法得出确定 A/B 结果。</p></aside></div>`+footer()}
function learning(){return head('LEARNING → NEXT CYCLE','经验必须重新进入工作','保留适用范围、证据与反例；一次成功不能变成对所有账号的万能规则。',btn('从经验创建选题','learning-topic','','primary'))+employee('苏澈','学习与分析负责人','让结果影响下一轮，不替 CEO 静默改策略')+`<div class="split"><div><div class="section"><h2>可调用的经验</h2>${S.learning.map(l=>`<div class="listrow"><div><h3>${esc(l.title)}</h3><p>${esc(l.scope)} · ${esc(l.basis)}</p><p>用法：${esc(l.use)}</p></div><div class="row-actions">${state(l.state)}${l.state==='候选'?btn('确认沉淀','learning-accept',`data-id="${l.id}"`,'small'):btn('用于下一选题','learning-topic',`data-id="${l.id}"`,'small')}</div></div>`).join('')}</div><div class="section"><h2>下一轮准备</h2><p>选用一条有范围的经验，提出新选题与验证方式；结果出来后修订、缩小范围或停用经验。</p></div></div><aside class="paper"><h2>不是知识库尽头</h2><p>Learning 进入下一选题、Proposal、制作 Work 或经营策略建议，都要显示“引用了什么”和“改变什么”。</p><p class="meta">重大策略变化仍由 CEO 确认。</p></aside></div>`+footer()}
function assets(){let a=S.assets.find(x=>x.id===route.id);if(route.view==='detail'&&a)return assetDetail(a);return head('PRODUCTION RESOURCES','制作可用资源','资产、授权与已验证内容组件可以被制作 Work 调用；数字人是出镜资产，不是 AI 员工。',btn('导入本地文件','asset-form','','primary'))+employee('乔叶','素材与视觉责任人','在制作时提供合法可用资源')+`<div class="asset-grid">${S.assets.map(a=>`<article class="asset"><div class="asset-preview">${a.kind==='数字人'?'人':a.kind==='视频'?'▶':a.kind==='图片'?'▧':'▤'}</div><div class="asset-info"><strong>${esc(a.name)}</strong><p>${esc(a.kind)} · ${esc(a.version)}</p>${state(a.rights.includes('待')||a.rights.includes('需')?'授权待确认':'可用')}<div style="margin-top:9px">${btn('查看使用','jump',`data-to="assets/detail/${a.id}"`,'small')}</div></div></article>`).join('')}</div><div class="section"><h2>可复用内容组件</h2><p class="meta">可引用研究区的 Hook、Structure、Reference 片段与已接受 Learning；这些仍保留原对象身份，不复制成另一份素材。</p>${btn('查看拆解方法','jump','data-to="research/reference/ref0"')}</div>`+footer()}
function assetDetail(a){return head('ASSET',a.name,`${a.kind} · ${a.version} · ${a.rights}`,btn('返回素材','jump','data-to="assets/library"'))+employee('乔叶','素材负责人',a.name+' · 授权与复用')+`<div class="split"><div class="paper"><div class="asset-preview" style="height:290px;font-size:76px">${a.kind==='数字人'?'人':a.kind==='视频'?'▶':'▤'}</div><div class="section"><h2>如何进入制作</h2><p>${esc(a.used)}</p>${a.used.startsWith('W-')?btn('回到使用它的 Work','jump',`data-to="production/work/${a.used.slice(0,5).toLowerCase().replace('w-','w')==='w-202'?'w2':a.used.includes('201')?'w1':'w2'}"`):''}</div></div><aside class="paper"><h2>使用合同</h2><dl class="anatomy"><dt>类型</dt><dd>${esc(a.kind)}</dd><dt>版本</dt><dd>${esc(a.version)}</dd><dt>授权</dt><dd>${esc(a.rights)}</dd><dt>历史使用</dt><dd>${esc(a.used)}</dd></dl>${a.kind==='数字人'?'<p class="meta">人设、外观、声音、授权、版本、适用范围与历史使用需要维护；当前演示不生成真实数字人。</p>':''}</aside></div>`+footer()}
function render(){shell();let html=route.area==='operate'?operate():route.area==='research'?research():route.area==='production'?production():route.area==='publish'?publish():route.area==='accounts'?accounts():route.area==='analytics'?analytics():assets();$('#main').innerHTML=html;renderDrawer();document.title=`${navs.find(x=>x[0]===route.area)[1]} · Curis Content Growth`;}
function notify(msg){let old=$('.toast');if(old)old.remove();let el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3200)}
function openDrawer(name,context){drawer={name,context};renderDrawer();$('#drawer textarea')?.focus()}
function renderDrawer(){const el=$('#drawer');if(!drawer){el.hidden=true;el.innerHTML='';return}el.hidden=false;let ms=S.messages.filter(m=>m.context===drawer.context&&m.name===drawer.name);el.innerHTML=`<div class="drawer-head"><span class="avatar">${esc(drawer.name[0])}</span><div><strong>${esc(drawer.name)}</strong><small>当前上下文：${esc(drawer.context)}</small></div>${btn('关闭','close-drawer','','small')}</div><div class="drawer-thread"><div class="bubble"><small>${esc(drawer.name)} · 负责员工</small>我会沿着当前对象和版本继续讨论。提出建议不会自动改写正式成品；确认后才进入原工作。</div>${ms.map(m=>`<div class="bubble ${m.role==='user'?'user':''}"><small>${m.role==='user'?'你':esc(drawer.name)}</small>${esc(m.text)}</div>`).join('')}</div><form id="chat-form" class="drawer-compose"><label for="chat-text">就当前工作交流</label><textarea id="chat-text" name="text" required placeholder="说说要调整什么、为什么，或让员工解释当前判断…"></textarea><div class="actions"><small>演示回复 · 不调用真实模型</small><button class="primary" type="submit">发送</button></div></form>`;el.querySelector('.drawer-thread').scrollTop=el.querySelector('.drawer-thread').scrollHeight}
function form(title,fields,action,values={}){openDrawer('当前工作区团队',title);$('#drawer .drawer-thread').innerHTML=`<form id="edit-form" data-action="${action}"><h2>${esc(title)}</h2>${fields.map(f=>`<div class="field"><label for="f-${f.name}">${esc(f.label)}</label>${f.type==='select'?`<select id="f-${f.name}" name="${f.name}">${f.options.map(x=>`<option value="${attr(x)}" ${values[f.name]===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea id="f-${f.name}" name="${f.name}" ${f.required?'required':''}>${esc(values[f.name]||'')}</textarea>`:`<input id="f-${f.name}" name="${f.name}" type="${f.type||'text'}" value="${attr(values[f.name]||'')}" ${f.required?'required':''}>`}</div>`).join('')}<div class="actions"><button type="submit" class="primary">确认</button>${btn('取消','close-drawer')}</div></form>`;$('#drawer .drawer-compose').hidden=true;$('#drawer input, #drawer select, #drawer textarea')?.focus()}
function act(name,el){const id=el.dataset.id,to=el.dataset.to;switch(name){case'jump':{let [a,v,x]=to.split('/');go(a,v,x);break}case'reset':if(confirm('只重置本地演示数据？')){S=copy(SEED);save();go('operate','portfolio');notify('演示已重置')}break;case'chat':openDrawer(el.dataset.person||'团队',el.dataset.context||'当前工作');break;case'close-drawer':drawer=null;renderDrawer();break;case'next-cycle':S.activity.unshift({kind:'进行中',text:'林岚已在既定边界内检查下一轮选题准备',time:'刚刚'});save();notify('下一轮准备已加入团队动态');render();break;
case'watch-form':{let w=S.watch.find(x=>x.id===id);form(w?'修改持续关注':'新增持续关注',[{name:'name',label:'关注关键词 / 账号 / 话题',required:true},{name:'platform',label:'观察平台',type:'select',options:['抖音','小红书','公众号','跨平台']},{name:'kind',label:'关注类型',type:'select',options:['关键词 + 话题','对标账号','受众反馈','榜单入口']},{name:'frequency',label:'检查频率',type:'select',options:['每 6 小时','每日','每周']}],'watch',w||{});$('#edit-form').dataset.id=id||'';break}case'watch-toggle':{let w=S.watch.find(x=>x.id===id);w.state=w.state==='已暂停'?'运行中':'已暂停';save();render();break}case'watch-check':{let w=S.watch.find(x=>x.id===id);w.last='刚刚';save();render();notify('已记录演示检查；没有连接真实来源');break}case'watch-remove':if(confirm('移除此条关注？')){S.watch=S.watch.filter(x=>x.id!==id);save();render()}break;
case'signal-to-ref':{let s=S.signals.find(x=>x.id===id),old=S.refs.find(r=>r.signal===id);if(old){go('research','reference',old.id);break}let r={id:'ref'+Date.now(),title:s.title,source:s.source,published:'未知',captured:'刚刚',signal:id,hook:'从目标受众的问题切入',opening:'用具体场景说明话题',structure:'问题 → 证据 → 方法 → 行动',rhythm:'短周期；待观察',visual:'示意画面；未复制来源',cta:'给受众一个可实践的下一步',feedback:'暂无可验证评论样本',why:'与当前账号经营方向有关，但需要更多证据。',evidence:s.source+' · '+s.seen,fit:s.platform+'相关账号',limit:'原内容不可直接复制；表现原因未验证。',pattern:'先以受众问题建立兴趣，再给可操作方法'};S.refs.unshift(r);save();go('research','reference',r.id);break}
case'ref-to-topic':{let r=ref(id),old=S.topics.find(t=>t.from===id);if(old){go('research','topics');notify('已存在来源相同的选题');break}S.topics.unshift({id:'topic'+Date.now(),title:'把“'+r.title+'”转成可操作清单',stage:'待完善',account:'a1',from:id,note:'引用 Pattern：'+r.pattern});save();go('research','topics');notify('已形成选题，来源仍可追溯');break}
case'topic-to-proposal':{let t=S.topics.find(x=>x.id===id),old=S.proposals.find(p=>p.topic===id);if(old){go('research','proposal',old.id);break}let p={id:'prop'+Date.now(),title:t.title,account:t.account||'a1',why:'来源选题与账号当前方向相符',goal:'测试可执行内容的收藏与有效反馈',method:'图文',criterion:'发布后 7 天与该账号同形式内容比较',source:t.from,topic:id,limits:'来源内容不可复制；需核对事实与授权',state:'待开工'};S.proposals.unshift(p);t.stage='已形成提案';save();go('research','proposal',p.id);break}
case'proposal-start':{let p=S.proposals.find(x=>x.id===id);if(!p.account||!account(p.account)){notify('请先确认合法目标账号');break}let old=S.works.find(w=>w.source===id);if(old){go('production','work',old.id);break}let w={id:'w'+Date.now(),title:p.title,account:p.account,method:p.method,step:p.method==='图文'?'页序与文案':'脚本',owner:p.method==='图文'?'周砚':'徐白',collab:'乔叶',state:'制作中',version:1,artifact:p.method==='图文'?'五页图文候选':'脚本候选',source:id,next:'产出初版后请员工把关',review:false,accepted:false};S.works.unshift(w);p.state='制作中';save();go('production','work',w.id);break}
case'step-note':{let w=work(id);notify(`${el.dataset.step} · ${w.owner}负责；可在此 Work 与负责人讨论，不改变执行`);break}
case'inline-toggle':inlineOpen[id]=!inlineOpen[id];render();if(inlineOpen[id])$('#inline-text')?.focus();break;
case'inline-open':inlineOpen[id]=true;render();$('#inline-text')?.focus();break;
case'select-inline':{let w=work(id);selections[id]={objectId:id,version:w.version,locator:el.dataset.locator,excerpt:el.dataset.excerpt,anchor:el.dataset.anchor};inlineOpen[id]=true;render();$('#inline-text')?.focus();break}
case'selection-locate':{let sel=selections[id];document.getElementById(sel?.anchor)?.scrollIntoView({block:'center',behavior:'smooth'});break}
case'selection-remove':delete selections[id];render();break;
case'revise':{let w=work(id),sel=selections[id];if(sel&&sel.version!==w.version){notify('所选版本已变化；请重新选择或比较旧版本');break}let before=sel?.excerpt||w.artifact,after=sel?.locator.includes('脚本第 1 段')?'先选一件你今天正在做的事：AI 能接哪一步？':sel?.locator.includes('脚本')?'把这段方法说得更具体，保留原本的事实边界。':sel?.locator.includes('镜头')?before+' · 增加能说明观点的具体画面':before+' · 调整为更清楚的呈现顺序';w.candidate={baseVersion:w.version,targetVersion:w.version+1,locator:sel?.locator||'当前产物',anchor:sel?.anchor||'',before,after,createdBy:w.owner};save();render();document.getElementById('candidate-result')?.scrollIntoView({block:'center',behavior:'smooth'});break}
case'candidate-accept':{let w=work(id),c=w?.candidate;if(!c||c.baseVersion!==w.version){notify('候选基线已变化，请重新比较');break}let m=c.locator.match(/脚本第 (\d+) 段/),shot=c.locator.match(/镜头 (\d+)/),page=c.locator.match(/页 (\d+)/);if(m){w.scriptParts ||= ['你担心 AI 会抢走你的工作吗？先看你每天做的五件事。','把重复搜集、整理、初稿交给工具；把判断和关系留给自己。','今天选一项工作，试着拆成目标、输入、检查三个步骤。'];w.scriptParts[Number(m[1])-1]=c.after;w.videoNeedsReview=true;w.artifact=w.artifact.replace(/Script v\d+/,`Script v${c.targetVersion}`)}else if(shot){w.shots ||= ['开场疑问','真实工作场景','任务拆解','关键对照','可做的第一步','收束'];w.shots[Number(shot[1])-1]=c.after}else if(page){w.pages ||= ['封面','问题','拆解','方法','行动'];w.pages[Number(page[1])-1]=c.after}else w.artifact=c.after;w.version=c.targetVersion;w.review=false;w.accepted=false;w.state='修订待审';w.candidate=null;save();render();notify(`已采纳 ${c.locator} 的 v${w.version} 修订；需重新把关，未核验视频或发布`);break}
case'candidate-reject':{let w=work(id);if(w){w.candidate=null;save();render()}break}
case'review':{let w=work(id);w.review=true;w.state='待确认';save();render();break}case'accept':{let w=work(id);if(!w.review){notify('先完成员工审查');break}w.accepted=true;w.state='已接受待发布';save();render();break}
case'create-pub':{let w=work(id);if(!w?.accepted){notify('成品尚未正式接受');break}let old=S.publications.find(p=>p.work===id);if(old){go('publish','item',old.id);break}let p={id:'pub'+Date.now(),work:id,account:w.account,version:w.version,mode:account(w.account)?.status==='手动发布'?'人工发布':'演示发布',state:'等待人工发布',receipt:'尚无外部回执',window:'发布确认后 7 天',url:''};S.publications.unshift(p);save();go('publish','item',p.id);break}
case'pub-package':notify('演示：发布包清单已准备；没有生成真实下载或外部提交');break;case'pub-unknown':{let p=S.publications.find(x=>x.id===id);p.state='外部效果未知';p.receipt='用户报告已操作；缺少平台链接与回执，禁止重发';save();render();break}case'verify-form':form('核验外部发布',[{name:'url',label:'发布链接或平台回执（演示文本）',required:true},{name:'when',label:'实际发布时间',type:'datetime-local',required:true},{name:'source',label:'核验依据',type:'select',options:['人工查看平台页面','平台回执截图','平台 API 回执']}],'verify');$('#edit-form').dataset.id=id;break;
case'account-form':{let a=account(id);form(a?'修改账号档案':'添加账号档案',[{name:'platform',label:'平台',type:'select',options:['小红书','抖音','公众号','其他']},{name:'name',label:'账号名称',required:true},{name:'focus',label:'内容定位',required:true},{name:'goal',label:'经营目标',required:true}],'account',a||{});$('#edit-form').dataset.id=id||'';break}case'account-remove':{let a=account(id);if(S.works.some(w=>w.account===id)||S.publications.some(p=>p.account===id)){notify('该账号已有 Work / 发布历史，保留稳定身份；可修改准备状态');break}if(confirm('移除本地演示账号档案？')){S.accounts=S.accounts.filter(x=>x.id!==id);save();go('accounts','index')}break}
case'metric':metric=id;render();break;case'compare':compareMode=id;render();break;case'data-form':{let o=S.observations.find(x=>x.id===id);form('补录内容表现',[{name:'views',label:'播放量（累计）',type:'number',required:true},{name:'saves',label:'收藏数（累计）',type:'number',required:true},{name:'follows',label:'新增粉丝（累计）',type:'number',required:true},{name:'completion',label:'完播率 %',type:'number',required:true},{name:'source',label:'来源说明',required:true}],'data',{views:o.views.at(-1),saves:o.saves.at(-1),follows:o.follows.at(-1),completion:o.completion.at(-1),source:o.source});$('#edit-form').dataset.id=id;break}
case'learning-candidate':{let old=S.learning.find(x=>x.title==='问题式开头值得在同账号继续验证');if(!old){S.learning.unshift({id:'learn'+Date.now(),title:'问题式开头值得在同账号继续验证',scope:'抖音｜创始人 IP｜口播',basis:'W-202 v2 的手动观察 + 评论样本；不能证明因果',confidence:'单次观察 · 待复验',state:'候选',use:'下一条保持账号和形式，测试开头结构'});save()}go('analytics','learning');break}case'learning-accept':{let l=S.learning.find(x=>x.id===id);l.state='已接受';save();render();break}case'learning-topic':{let l=S.learning.find(x=>x.id===id)||S.learning.find(x=>x.state==='已接受');if(!l||l.state!=='已接受'){notify('先确认经验适用范围');break}let t={id:'topic'+Date.now(),title:'下一轮：'+l.title,stage:'待完善',account:l.scope.includes('抖音')?'a2':'a1',from:l.id,note:'引用经验「'+l.title+'」；改变开头 / 结构，继续验证适用性'};S.topics.unshift(t);save();go('research','topics');notify('下一轮选题已引用经验，来源可追溯');break}
case'asset-form':form('导入本地素材',[{name:'file',label:'选择本地文件',type:'file',required:true},{name:'kind',label:'资产类型',type:'select',options:['图片','视频','音频','模板','数字人']},{name:'rights',label:'授权与使用范围',required:true}],'asset');break;
}}
function submitEdit(f){let d=new FormData(f),v=Object.fromEntries(d.entries()),action=f.dataset.action,id=f.dataset.id;if(action==='watch'){let w=S.watch.find(x=>x.id===id);if(w)Object.assign(w,v);else S.watch.unshift({id:'watch'+Date.now(),...v,state:'运行中',last:'尚未检查',method:'手动定义 · Mock'});go('research','watch')}else if(action==='verify'){let p=S.publications.find(x=>x.id===id);if(p){p.state='已核验上线';p.receipt=v.source+' · '+v.when;p.url=v.url;go('publish','item',id)}}else if(action==='account'){let a=account(id);if(a)Object.assign(a,v);else{a={id:'a'+Date.now(),...v,mark:v.platform[0],stage:'待确认',rhythm:'待定',supply:'未知',owner:'林岚',status:'未连接',note:'账号已记录，尚未核验权限与数据可用性。'};S.accounts.push(a)}go('accounts','detail',a.id)}else if(action==='data'){let o=S.observations.find(x=>x.id===id);if(o){for(const k of ['views','saves','follows','completion'])o[k].push(Number(v[k]));o.source=v.source+' · 人工订正';o.window='最近 '+o.views.length+' 次观察';go('analytics','overview')}}else if(action==='asset'){let file=d.get('file');if(!file?.name){notify('请选择本地文件');return}S.assets.unshift({id:'asset'+Date.now(),name:file.name,kind:v.kind,version:'v1',rights:v.rights,used:'尚未关联 Work'});go('assets','library');notify('已保存文件名称与授权说明；原型不上传或保存文件内容')}save();drawer=null;renderDrawer();render()}
function submitInlineChat(f){let w=work(f.dataset.id),t=f.elements.text.value.trim();if(!w||!t)return;let selected=selections[w.id];if(selected&&selected.version!==w.version){notify('所选段落基线已变化；保留草稿，请重新选择或比较');return}S.messages.push({role:'user',name:w.owner,context:w.id,text:t,selection:selected?copy(selected):null});S.messages.push({role:'employee',name:w.owner,context:w.id,text:'已收到这条工作意见。若需要实际改变产物，请形成修订候选；候选会回到下方专业 Main，供你比较与选择。'});inlineDraft[w.id]='';save();render();$('#inline-text')?.focus()}
function submitChat(f){let t=f.elements.text.value.trim();if(!t)return;S.messages.push({role:'user',name:drawer.name,context:drawer.context,text:t});S.messages.push({role:'employee',name:drawer.name,context:drawer.context,text:'已收到。演示中我会把这条意见保留在当前工作上下文；若要影响正式产物，请在原 Work 中生成修订候选并重新把关。'});save();renderDrawer()}
document.addEventListener('click',e=>{let el=e.target.closest('[data-go],[data-act]');if(!el)return;if(el.dataset.go){let [a,v,id]=el.dataset.go.split('/');go(a,v,id)}else act(el.dataset.act,el)});
document.addEventListener('change',e=>{if(e.target.id==='account-scope'){scope=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='inline-text')inlineDraft[e.target.closest('form')?.dataset.id]=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id==='edit-form'){e.preventDefault();submitEdit(e.target)}if(e.target.id==='chat-form'){e.preventDefault();submitChat(e.target)}if(e.target.id==='inline-chat-form'){e.preventDefault();submitInlineChat(e.target)}});
window.addEventListener('hashchange',parse);parse();
})();
